cd /ssd/Strata; L=strata-iq3_s.log; echo "=== snapshot size vs token count (from the real run) ==="; grep -oE "skip parking \(snapshot [0-9]+ MiB" $L | grep -oE "[0-9]+" | sort -n | awk 'NR==1{print "min:",$1,"MiB"} {a[NR]=$1} END{print "max:",a[NR],"MiB"}'; echo; echo "=== conversations that DID park ==="; grep -oE "saved [0-9]+ B" $L | grep -vE "saved 0 B" | sort -u | head -5; echo; echo "=== free RAM now ==="; grep MemAvailable /proc/meminfo | awk '{printf "%.1f GiB\n", $2/1048576}'
